function q96h($sql,$p=[]){global $pdo;$s=$pdo->prepare($sql);$s->execute($p);return $s->fetchAll(PDO::FETCH_ASSOC);}
function x96h($sql,$p=[]){global $pdo;$s=$pdo->prepare($sql);$s->execute($p);return (int)$pdo->lastInsertId();}
